-- phase12_restore_ledger_from_backup.sql
-- Restores Transaction_Ledger from the clean backup (Arul Finance Backup 2026-09-10),
-- assigning every row a fresh UNIQUE numeric Ref_ID (the backup's Ref_IDs were huge
-- numbers that had collapsed to duplicates, which is what made one edit hit many rows).
-- Nothing references ledger Ref_IDs, so reassigning them is safe. Run once in the
-- Supabase SQL editor, then hard-refresh the app.

begin;
-- Drop the UNIQUE constraint if it already exists (this also removes its backing
-- index — never drop the index directly, Postgres refuses while the constraint owns it).
alter table "Transaction_Ledger" drop constraint if exists "Transaction_Ledger_Ref_ID_key";
delete from "Transaction_Ledger";









alter table "Transaction_Ledger" add constraint "Transaction_Ledger_Ref_ID_key" unique ("Ref_ID");
commit;

-- Verify (both should be 0):
--   select count(*) from (select "Ref_ID" from "Transaction_Ledger" group by "Ref_ID" having count(*)>1) x;
--   select count(*) from "Transaction_Ledger" where "Ref_ID" is null or "Ref_ID"='';